import org.springframework.context.ApplicationContext;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class EnterpriseApplication {

    @Bean
    public String dataSourceUrl() {
        return "jdbc:postgresql://localhost:5432/production_db";
    }

    public static void main(String[] args) {
        // Bootstrapping the advanced ApplicationContext container
        ApplicationContext context = new AnnotationConfigApplicationContext(EnterpriseApplication.class);

        // Retrieving a bean by type with automatic casting
        String url = context.getBean(String.class);
        System.out.println("Configured DataSource URL: " + url);

        // Demonstrating enterprise capability: checking for environment definitions
        boolean containsBean = context.containsBean("dataSourceUrl");
        System.out.println("Container manages dataSourceUrl: " + containsBean);
    }
}
